-- Modify "orders" table
ALTER TABLE `orders` DROP CHECK `orders_chk_4`, ADD CONSTRAINT `orders_chk_4` CHECK (char_length(`order_reference`) <= 255), DROP CHECK `orders_chk_5`, ADD CONSTRAINT `orders_chk_5` CHECK (char_length(trim(`shipping_address`)) between 1 and 255), DROP CHECK `orders_chk_6`, ADD CONSTRAINT `orders_chk_6` CHECK (`total_amount` >= `shipping_cost`), DROP CHECK `orders_chk_7`, ADD CONSTRAINT `orders_chk_7` CHECK (lower(`status`) = `order_status`), ADD CONSTRAINT `orders_chk_8` CHECK ((`order_reference` is not null) and (char_length(trim(`order_reference`)) > 0));
